<?php
declare(strict_types=1);require __DIR__.'/test_client.php';require_once __DIR__.'/../src/platform/trips.php';require_once __DIR__.'/../src/platform/settlement.php';
function settle_review(string $id,string $reviewer,bool $execute=true):array{$r=row('SELECT * FROM rs_requests WHERE id=?',[$id]);ok_api('request-decision',['id'=>$id,'version'=>$r['version'],'proposal_hash'=>$r['proposal_hash'],'decision'=>'approved','reason'=>'Independent settlement fixture review'],$reviewer);if($execute)ok_api('request-execute',['id'=>$id,'version'=>(int)$r['version']+1,'proposal_hash'=>$r['proposal_hash'],'evidence'=>'Isolated test evidence, no real money'],$reviewer);return $r;}
try{
 $finance=login_fixture('finance');$other=login_fixture('finance_reviewer');$support=login_fixture('support');$customer=login_fixture('customer');$pass=bin2hex(random_bytes(10));$phone='+88019'.random_int(10000000,99999999);
 sql('INSERT INTO rs_users(name,phone,password_hash,preferences) VALUES(?,?,?,?)',['Test settlement lifecycle',$phone,password_hash($pass,PASSWORD_DEFAULT),'{}']);$id=(int)connection()->lastInsertId();sql('INSERT INTO rs_roles(user_id,role_key) VALUES(?,"driver")',[$id]);sql('INSERT INTO rs_drivers(user_id,status,identity_status) VALUES(?,"approved","approved")',[$id]);$driver=ok_api('login',['phone'=>$phone,'password'=>$pass,'client'=>'android','device'=>'Settlement fixture'])['token'];
 transaction(function()use($id){journal(['id'=>$id],'fixture_grant','fixture:'.identifier(),null,[['account'=>'driver_cost','amount'=>10000],['account'=>'driver_payable','user'=>$id,'amount'=>-10000]],'Isolated integration fixture; no actual funds');return [];});
 $dest=ok_api('create-request',['kind'=>'payout_destination','reason'=>'Local original destination','password'=>$pass,'payload'=>['destination'=>'Fixture destination A','evidence'=>'Test ownership evidence A']],$driver)['request_id'];settle_review($dest,$finance);
 $pay=ok_api('create-request',['kind'=>'payout','reason'=>'Local payout snapshot fixture','payload'=>['amount_minor'=>1000]],$driver)['request_id'];$pr=settle_review($pay,$finance,false);
 $change=ok_api('create-request',['kind'=>'payout_destination','reason'=>'Local changed destination','password'=>$pass,'payload'=>['destination'=>'Fixture destination B','evidence'=>'Test ownership evidence B']],$driver)['request_id'];check(settlement_state($id)['pending_destination_review'],'Pending destination changes are visible and pause settlement');
 [$s]=call_api('request-execute',['id'=>$pay,'version'=>2,'proposal_hash'=>$pr['proposal_hash'],'evidence'=>'Must remain held'],$finance);check($s===409&&!row('SELECT id FROM rs_journals WHERE reference_key=?',['payout:'.$pay]),'A pending destination review blocks an already approved payout without recording cash');
 [$s]=call_api('request-withdraw',['id'=>$change,'version'=>1,'reason'=>'Attempt other account cancellation'],$customer);check($s===403,'Only the requester can withdraw their pending destination proposal');ok_api('request-withdraw',['id'=>$change,'version'=>1,'reason'=>'Fixture destination withdrawn'],$driver);check(!settlement_state($id)['pending_destination_review'],'Withdrawing a pending change releases its review pause');
 $new=ok_api('create-request',['kind'=>'payout_destination','reason'=>'Local changed destination','password'=>$pass,'payload'=>['destination'=>'Fixture destination B','evidence'=>'Test ownership evidence B']],$driver)['request_id'];settle_review($new,$finance);$snapshot=decode(row('SELECT payload FROM rs_requests WHERE id=?',[$pay])['payload']);check($snapshot['destination_request']===$dest&&$snapshot['destination_snapshot']['destination']==='Fixture destination A','New destination approval preserves the original approved payout snapshot');
 [$s]=call_api('create-request',['kind'=>'payout_hold','reason'=>'Support hold attempt','payload'=>['user_id'=>$id,'held'=>true,'version'=>0]],$support);check($s===403,'Ordinary support cannot propose a financial settlement hold');
 $hold=ok_api('create-request',['kind'=>'payout_hold','reason'=>'Fixture finance review hold','payload'=>['user_id'=>$id,'held'=>true,'version'=>0]],$finance)['request_id'];settle_review($hold,$other);check(settlement_state($id)['held'],'An independently approved finance hold is durable');
 [$s]=call_api('create-request',['kind'=>'payout','reason'=>'Held account attempt','payload'=>['amount_minor'=>1000]],$driver);check($s===409,'Held settlement cannot create new payout proposals');[$s]=call_api('request-execute',['id'=>$pay,'version'=>2,'proposal_hash'=>$pr['proposal_hash'],'evidence'=>'Held execution attempt'],$finance);check($s===409,'A hold blocks actual execution of an existing payout');
 $release=ok_api('create-request',['kind'=>'payout_hold','reason'=>'Fixture reviewed hold release','payload'=>['user_id'=>$id,'held'=>false,'version'=>1]],$finance)['request_id'];settle_review($release,$other);check(!settlement_state($id)['held'],'Hold release requires a separate independent decision');
 sql('UPDATE rs_drivers SET identity_status="pending" WHERE user_id=?',[$id]);[$s]=call_api('request-execute',['id'=>$pay,'version'=>2,'proposal_hash'=>$pr['proposal_hash'],'evidence'=>'Pending identity attempt'],$finance);check($s===409,'Execution rechecks driver identity after proposal approval');sql('UPDATE rs_drivers SET identity_status="approved" WHERE user_id=?',[$id]);
 ok_api('request-execute',['id'=>$pay,'version'=>2,'proposal_hash'=>$pr['proposal_hash'],'evidence'=>'Fixture confirmed original destination A; no real funds'],$finance);$journal=row('SELECT evidence FROM rs_journals WHERE reference_key=?',['payout:'.$pay]);check(decode($journal['evidence'])['destination_snapshot']['destination']==='Fixture destination A','Actual payout journal records the original destination snapshot');
 $dispatch=login_fixture('dispatch');$trip=decode(file_get_contents(__DIR__.'/../.local/verification/browser-test-trip.json'))['id'];$masked=ok_api('trip',null,$dispatch,['id'=>$trip])['trip'];$reveal=ok_api('trip-reveal',['trip_id'=>$trip,'purpose'=>'Local explicit privacy regression'],$dispatch)['trip'];check((float)$masked['snapshot']['pickup']['lat']!==(float)$reveal['snapshot']['pickup']['lat'],'Staff location remains coarse until a reasoned reveal');
 $session=row('SELECT id FROM rs_sessions WHERE token_hash=?',[hash('sha256',$dispatch)])['id'];sql('UPDATE rs_trip_reveals SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 SECOND) WHERE session_id=? AND trip_id=?',[$session,$trip]);$expired=ok_api('trip',null,$dispatch,['id'=>$trip])['trip'];check((float)$expired['snapshot']['pickup']['lat']===(float)$masked['snapshot']['pickup']['lat'],'Expired sensitive reveal restores masking in the same session');
 check((int)sql('SELECT COUNT(*) FROM (SELECT journal_id FROM rs_entries GROUP BY journal_id HAVING SUM(amount_minor)<>0) x')->fetchColumn()===0,'Every settlement journal remains balanced');
 file_put_contents(__DIR__.'/../.local/backend/settlement-controls-verification.json',j(['passed'=>$checks,'time'=>gmdate('c')]));echo "Verified {$checks} settlement and reveal checks.\n";
}catch(Throwable $e){fwrite(STDERR,$e->getMessage()."\n");exit(1);}
